package com.meridiantrust.sentinel.api;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.bind.MethodArgumentNotValidException; import java.time.*; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler({IllegalArgumentException.class,MethodArgumentNotValidException.class}) @ResponseStatus(HttpStatus.BAD_REQUEST) Map<String,Object> bad(Exception e){return error("VALIDATION_ERROR",e.getMessage());} @ExceptionHandler(NoSuchElementException.class) @ResponseStatus(HttpStatus.NOT_FOUND) Map<String,Object> missing(Exception e){return error("NOT_FOUND",e.getMessage());} private Map<String,Object> error(String code,String m){return Map.of("timestamp",Instant.now().toString(),"code",code,"message",m==null?code:m);}}
